"""Deterministic CPU structural-policy experiments, with no model dependency.

All response streams and tokenizers here are synthetic fixtures. Verification
implements exact committed-prefix matching, not GPU logits or cache arithmetic.
Run: python3 structural_testbed.py --output-dir structural_results
"""

import argparse
import hashlib
import json
import random
import re
from collections import Counter, defaultdict
from pathlib import Path

from method import draft, reuse_tokens


SEEDS = (17, 29, 43, 71, 101)
FORMATS = ("terse", "label", "sentence", "numbered", "table", "json", "unicode", "changed_repeat")
TEMPLATES = ("The answer is ", "The correct answer is ", "Answer: ", "Final answer: ")
EOS = 0
MERGED = re.compile(r"[ \t]*[A-Za-z0-9_]+|[ \t]*[^\w\s]|[ \t]+|\n|\S")
COSTS = {
    "lean_block": dict(policy=0.005, block_fixed=0.25, block_per_token=0.05, rollback=0.05),
    "moderate_block": dict(policy=0.01, block_fixed=0.6, block_per_token=0.10, rollback=0.15),
    "costly_block": dict(policy=0.04, block_fixed=1.2, block_per_token=0.25, rollback=0.4),
}


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, ensure_ascii=True,
                                     separators=(",", ":")).encode()).hexdigest()


def pieces(text, mode):
    result = list(text) if mode == "character" else MERGED.findall(text)
    assert "".join(result) == text, repr(text)
    return result


class Tokenizer:
    """Fixed synthetic vocabulary; whitespace-merging is a boundary stressor."""

    def __init__(self, texts, mode):
        self.mode = mode
        vocabulary = {part for text in texts for part in pieces(text, mode)}
        # Grammar drafts can start/end inside words, unlike full target strings.
        for template in TEMPLATES:
            for begin in range(len(template)):
                for end in range(begin + 1, len(template) + 1):
                    vocabulary.update(pieces(template[begin:end], mode))
        self.to_id = {text: index + 1 for index, text in enumerate(sorted(vocabulary))}
        self.to_text = {index: text for text, index in self.to_id.items()}

    def encode(self, text):
        return [self.to_id[part] for part in pieces(text, self.mode)]

    def decode(self, tokens):
        return "".join(self.to_text[token] for token in tokens if token != EOS)


def fixtures(per_format=16):
    """Equal format weights are an experimental choice, not target frequencies."""
    records = []
    for seed in SEEDS:
        rng = random.Random(seed)
        for format_name in FORMATS:
            for index in range(per_format):
                answer = rng.choice("ABCD")
                color = rng.choice(("red", "green", "blue", "yellow"))
                other = rng.choice(("circle", "square", "triangle"))
                if format_name == "terse":
                    text = rng.choice((answer, "(" + answer + ")", answer + "."))
                elif format_name == "label":
                    text = rng.choice(("Answer: ", "Final answer: ", "ANSWER:\n")) + answer
                elif format_name == "sentence":
                    text = rng.choice(("The answer is ", "The correct answer is ",
                                       "I would choose ", "It appears to be ")) + answer + "."
                elif format_name == "numbered":
                    motif = "The image shows a " + color + " " + other + ". "
                    text = "".join(str(i + 1) + ". " + motif for i in range(rng.randrange(2, 5)))
                    text += "Therefore, the answer is " + answer + "."
                elif format_name == "table":
                    text = "| item | observation |\n|---|---|\n"
                    text += "".join("| " + str(i) + " | " + color + " " + other + " |\n"
                                    for i in range(rng.randrange(2, 5)))
                    text += "Answer: " + answer
                elif format_name == "json":
                    entries = [dict(color=color, shape=other) for _ in range(rng.randrange(2, 5))]
                    text = json.dumps(dict(objects=entries, answer=answer), separators=(",", ":"))
                elif format_name == "unicode":
                    text = rng.choice(("\u03bb: ", "\u7b54\u6848\uff1a", "\U0001f642 ", "```\n")) + answer
                    text += rng.choice(("\n", "", "\n```"))
                else:
                    # Identical contexts precede both repeats and contradictory continuations.
                    phrase = "The image shows a "
                    colors = [color, color, rng.choice(tuple(c for c in ("red", "green", "blue", "yellow") if c != color))]
                    rng.shuffle(colors)
                    text = " ".join(phrase + item + " " + other + "." for item in colors)
                    text += " Answer: " + answer
                records.append(dict(id=f"{seed}:{format_name}:{index}", seed=seed,
                                    format=format_name, text=text,
                                    early_stop_draw=rng.random(), early_stop_fraction=rng.random(),
                                    maximum=rng.choice((2, 4, 8, 32))))
    return records


def make_stream(record, tokenizer):
    tokens = tokenizer.encode(record["text"])
    if record["early_stop_draw"] < 0.20 and len(tokens) > 1:
        cut = 1 + int(record["early_stop_fraction"] * (len(tokens) - 1))
        tokens = tokens[:cut]
    return (tokens + [EOS])[:128]


def grammar(state, character_cap=4):
    """Text-only prefix grammar: complete labels but never select an answer."""
    cap = min(32, state["remaining_tokens"], state["maximum_draft_tokens"], character_cap)
    line = state["decoded_text"].rsplit("\n", 1)[-1]
    if cap <= 0:
        return []
    for template in TEMPLATES:
        if len(line) < len(template) and template.casefold().startswith(line.casefold()):
            return {"text": template[len(line):len(line) + cap]}
    return []


def complete_grammar(state):
    """Unsplit literal completion; simulated host encodes and caps the draft.

    This control removes arbitrary character cuts. Deploying it requires checking
    actual text-proposal host capping and actual tokenizer boundary behavior.
    """
    if min(state["remaining_tokens"], state["maximum_draft_tokens"]) <= 0:
        return []
    line = state["decoded_text"].rsplit("\n", 1)[-1]
    for template in TEMPLATES:
        if len(line) < len(template) and template.casefold().startswith(line.casefold()):
            return {"text": template[len(line):]}
    return []


class Adaptive:
    """Acceptance-history controller using only its own plans and public history.

    This comparison assumes one persistent instance, called after each commit for
    one response. Public history extension measures matching proposed IDs, not an
    explicit verifier acknowledgement. Inconsistent/reset histories clear state.
    No target logits, stream, or explicit acceptance feedback is exposed.
    """

    def __init__(self, tokenizer):
        self.tokenizer = tokenizer  # Synthetic trusted text encoding, testbed only.
        self.reset()

    def reset(self):
        self.stats = {arm: dict(hit=3, tried=4, horizon=2, cooldown=0, opportunities=0)
                      for arm in ("grammar", "reuse")}
        self.previous = None
        self.observed_updates = 0
        self.history_resets = 0

    def __call__(self, state):
        history = state["generated_token_ids"]
        if self.previous is not None:
            old, arm, proposal = self.previous
            if len(history) <= len(old) or history[:len(old)] != old:
                self.reset()
                self.history_resets += 1
            else:
                extension = history[len(old):]
                matched = 0
                for actual, expected in zip(extension, proposal):
                    if actual != expected:
                        break
                    matched += 1
                stats = self.stats[arm]
                stats["hit"] += matched
                stats["tried"] += len(proposal)

